<?php
namespace App\Services\AI;
use App\Support\Database;use App\Support\TenantContext;use App\Support\Auth;
final class AIOperationsService {
 public function decide(string $event,array $context=[]):array{$decision=$this->ruleFirst($event,$context);$i=Database::pdo()->prepare('INSERT INTO ai_interactions(tenant_id,user_id,client_id,client_service_id,event_type,provider,model_name,input_json,output_json,confidence,status,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,NOW())');$i->execute([TenantContext::id(),Auth::id(),$context['client_id']??null,$context['client_service_id']??null,$event,'rule-engine','deterministic-v1',json_encode($context),json_encode($decision),$decision['confidence'],'completed']);$iid=(int)Database::pdo()->lastInsertId();$d=Database::pdo()->prepare('INSERT INTO ai_decisions(tenant_id,ai_interaction_id,client_id,client_service_id,decision_type,decision,confidence,reason,sources_json,rules_json,requires_human,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,NOW())');$d->execute([TenantContext::id(),$iid,$context['client_id']??null,$context['client_service_id']??null,'next_action',$decision['action'],$decision['confidence'],$decision['reason'],json_encode($decision['sources']),json_encode($decision['rules']),$decision['requires_human']?1:0]);return $decision;}
 private function ruleFirst(string $event,array $c):array{$actions=['NEW_CLIENT'=>'identify_services','SERVICE_REQUESTED'=>'initialize_requirements','DOCUMENT_UPLOADED'=>'analyze_document','CLIENT_RESPONDED'=>'evaluate_response','DEADLINE_APPROACHING'=>'notify_and_escalate','PAYMENT_RECEIVED'=>'advance_billing','AUTHORITY_RESPONSE_RECEIVED'=>'process_authority_response','WORKFLOW_FAILED'=>'create_exception','CLIENT_INACTIVE'=>'follow_up'];$action=$actions[$event]??'human_review';$highRisk=in_array($event,['AUTHORITY_RESPONSE_RECEIVED','WORKFLOW_FAILED'],true);return ['action'=>$action,'confidence'=>$highRisk?0.75:0.92,'reason'=>'Deterministic orchestration rule selected from event type; external model is optional and cannot override approval gates.','sources'=>[],'rules'=>['event'=>$event],'requires_human'=>$highRisk];}
}
